  id INT AUTO_INCREMENT PRIMARY KEY,
  userId INT NOT NULL,
  addedBy INT NOT NULL,
  note VARCHAR(255),
  createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  UNIQUE INDEX mw_userId_idx (userId)
);

